package com.sq.motion;

import android.app.*;
import android.os.Bundle;
import android.graphics.*;
import android.view.*;
import android.widget.*;
import android.content.*;
import android.graphics.drawable.GradientDrawable;
import java.util.*;

public class MainActivity extends Activity {
  final int BG=Color.rgb(5,5,7), PANEL=Color.rgb(18,18,21), PURPLE=Color.rgb(113,25,190), WHITE=Color.WHITE, MUTED=Color.rgb(155,155,165);
  LinearLayout root, body; String page="home", projectName="Project 1", ratio="16:9", resolution="1080p"; int fps=30; ArrayList<String> projects=new ArrayList<>();
  int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);} 
  @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(Color.BLACK);getWindow().setNavigationBarColor(Color.BLACK);projects.add("Project 1");projects.add("Project 2");projects.add("Project 3");showHome();}
  GradientDrawable shape(int color,int stroke,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));if(stroke!=0)d.setStroke(dp(1),stroke);return d;}
  TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setGravity(Gravity.CENTER_VERTICAL);return t;}
  LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
  LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.HORIZONTAL);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
  void base(String title){root=column();root.setBackgroundColor(BG);setContentView(root);LinearLayout bar=row();bar.setPadding(dp(16),dp(10),dp(16),dp(10));TextView back=text(page.equals("home")?"◈  KEYFLOW":"‹",23,WHITE);bar.addView(back,new LinearLayout.LayoutParams(dp(48),dp(44)));back.setOnClickListener(v->{if(page.equals("home"))return;showHome();});TextView name=text(title,18,WHITE);name.setTypeface(null,1);bar.addView(name,new LinearLayout.LayoutParams(0,dp(44),1));root.addView(bar);ScrollView sc=new ScrollView(this);body=column();body.setPadding(dp(16),dp(8),dp(16),dp(16));sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));}
  TextView button(String s,boolean primary){TextView b=text(s,14,WHITE);b.setGravity(Gravity.CENTER);b.setPadding(dp(12),dp(12),dp(12),dp(12));b.setBackground(shape(primary?PURPLE:PANEL,primary?PURPLE:Color.rgb(48,48,54),14));return b;}
  void addButton(LinearLayout parent,String s,boolean p,Runnable action){TextView b=button(s,p);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(48));lp.setMargins(0,dp(6),0,dp(6));parent.addView(b,lp);b.setOnClickListener(v->action.run());}
  void heading(String s){TextView t=text(s,22,WHITE);t.setTypeface(null,1);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(56));body.addView(t,p);}
  void showHome(){page="home";base("مساحة عملك");TextView sub=text("SQ MOTION STUDIO",11,PURPLE);body.addView(sub);heading("مساحة عملك");for(int i=0;i<projects.size();i++){final String n=projects.get(i);LinearLayout r=row();r.setPadding(dp(12),dp(8),dp(12),dp(8));r.setBackground(shape(PANEL,Color.rgb(43,43,48),10));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(68));lp.setMargins(0,dp(4),0,dp(4));body.addView(r,lp);LinearLayout c=column();TextView nm=text(n,15,WHITE);nm.setTypeface(null,1);c.addView(nm);c.addView(text(resolution+"  ·  "+fps+" FPS  ·  "+ratio,11,MUTED));r.addView(c,new LinearLayout.LayoutParams(0,-1,1));r.addView(text("▧",25,PURPLE));r.setOnClickListener(v->{projectName=n;showEditor();});}
    View space=new View(this);body.addView(space,new LinearLayout.LayoutParams(1,dp(20)));addButton(body,"＋  مشروع جديد",true,()->newProject());addButton(body,"▱  استيراد ملف مشروع (.kf)",false,()->new AlertDialog.Builder(this).setMessage("استيراد ملفات المشاريع سيتم ربطه عند إضافة صيغة .kf الفعلية.").setPositiveButton("حسنًا",null).show());addButton(body,"⚙  الإعدادات",false,()->showSettings());}
  void newProject(){LinearLayout form=column();form.setPadding(dp(18),dp(8),dp(18),0);EditText name=new EditText(this);name.setSingleLine(true);name.setText("Project "+(projects.size()+1));name.setTextColor(WHITE);name.setHintTextColor(MUTED);form.addView(text("اسم المشروع",13,MUTED));form.addView(name);form.addView(text("نسبة العرض إلى الارتفاع",13,MUTED));Spinner ratios=spinner(new String[]{"16:9","9:16","1:1","4:5","4:3","3:4","3:2","21:9"});form.addView(ratios);form.addView(text("الدقة",13,MUTED));Spinner res=spinner(new String[]{"720p","1080p","4K"});res.setSelection(1);form.addView(res);form.addView(text("معدل الإطارات",13,MUTED));Spinner rate=spinner(new String[]{"24 FPS","30 FPS","60 FPS"});rate.setSelection(1);form.addView(rate);new AlertDialog.Builder(this).setTitle("مشروع جديد").setView(form).setNegativeButton("إلغاء",null).setPositiveButton("إنشاء",(d,w)->{projectName=name.getText().toString().trim();if(projectName.isEmpty())projectName="مشروع جديد";ratio=ratios.getSelectedItem().toString();resolution=res.getSelectedItem().toString();fps=Integer.parseInt(rate.getSelectedItem().toString().split(" ")[0]);projects.add(0,projectName);showEditor();}).show();}
  Spinner spinner(String[] values){Spinner s=new Spinner(this);ArrayAdapter<String>a=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,values);s.setAdapter(a);return s;}
  void showEditor(){page="editor";base(projectName);TextView meta=text("00:00:00 / 00:00:10                         3D      ⚙",12,MUTED);body.addView(meta,new LinearLayout.LayoutParams(-1,dp(38)));Stage stage=new Stage(this);LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,dp(220));sp.setMargins(0,dp(12),0,dp(12));body.addView(stage,sp);LinearLayout controls=row();String[] cs={"▦","Full","▮◀","▶","▶▮","▱","↶","↷"};for(String s:cs){TextView b=button(s,false);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(42),1);p.setMargins(dp(2),0,dp(2),0);controls.addView(b,p);}body.addView(controls);heading("الخط الزمني");TextView timeline=text("◆  "+projectName+"  ━━━━━━━━━━━━━━━━━━━",13,WHITE);timeline.setPadding(dp(10),dp(10),dp(10),dp(10));timeline.setBackground(shape(PANEL,PURPLE,8));body.addView(timeline,new LinearLayout.LayoutParams(-1,dp(46)));addButton(body,"＋  إضافة وسائط",false,()->new AlertDialog.Builder(this).setMessage("سيتم إضافة منتقي الوسائط في المرحلة التالية.").setPositiveButton("حسنًا",null).show());addButton(body,"＋  Solid Color",false,()->{projectName="Solid Color 1";showProperties();});addButton(body,"خصائص العنصر  ·  Edit",true,()->showProperties());addButton(body,"تصدير المشروع ↗",true,()->showExport());LinearLayout nav=row();for(String s:new String[]{"Media","نص","Solid","Adjustment","Null","Shape","Vector"}){TextView b=text(s,11,WHITE);b.setGravity(Gravity.CENTER);nav.addView(b,new LinearLayout.LayoutParams(0,dp(48),1));}body.addView(nav);}
  class Stage extends View{Paint p=new Paint(3);Stage(Context c){super(c);}protected void onDraw(Canvas c){super.onDraw(c);c.drawColor(Color.rgb(23,23,26));p.setColor(Color.rgb(8,8,10));c.drawRect(0,getHeight()*.18f,getWidth(),getHeight()*.82f,p);p.setColor(Color.rgb(31,31,35));p.setStrokeWidth(dp(1));for(int x=0;x<getWidth();x+=dp(24))c.drawLine(x,getHeight()*.18f,x,getHeight()*.82f,p);for(int y=(int)(getHeight()*.18f);y<getHeight()*.82f;y+=dp(24))c.drawLine(0,y,getWidth(),y,p);p.setColor(PURPLE);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(1));c.drawRect(1,getHeight()*.18f,getWidth()-1,getHeight()*.82f,p);p.setStyle(Paint.Style.FILL);}}
  void showProperties(){page="properties";base(projectName);heading("Attributes");field("الموقع X", "-960");field("الموقع Y","-540");field("المقياس (%)","100");field("الدوران","0");field("الشفافية (%)","100");addButton(body,"◆  إضافة إطار مفتاح",true,()->Toast.makeText(this,"تمت إضافة إطار مفتاح (واجهة أولية)",Toast.LENGTH_SHORT).show());addButton(body,"العودة إلى المحرر",false,()->showEditor());}
  void field(String label,String val){LinearLayout box=column();box.setPadding(dp(12),dp(8),dp(12),dp(8));box.setBackground(shape(PANEL,0,10));TextView t=text(label,12,MUTED);box.addView(t);SeekBar s=new SeekBar(this);s.setMax(200);s.setProgress(100);s.setProgressTintList(android.content.res.ColorStateList.valueOf(PURPLE));box.addView(s);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(68));lp.setMargins(0,dp(5),0,dp(5));body.addView(box,lp);}
  void showExport(){page="export";base("تصدير المشروع");TextView p=text(projectName,13,MUTED);body.addView(p);heading("صيغة إخراج الفيديو");body.addView(text("الدقة",13,MUTED));Spinner res=spinner(new String[]{"720p","1080p","4K"});res.setSelection(resolution.equals("4K")?2:resolution.equals("720p")?0:1);body.addView(res);body.addView(text("معدل الإطارات (FPS)",13,MUTED));Spinner rate=spinner(new String[]{"24 FPS","30 FPS","60 FPS"});rate.setSelection(fps==24?0:fps==60?2:1);body.addView(rate);addButton(body,"التقاط إطار (PNG)",false,()->new AlertDialog.Builder(this).setMessage("التقاط PNG يحتاج إضافة آلية حفظ الإطار إلى المعرض.").setPositiveButton("حسنًا",null).show());addButton(body,"تصدير المشروع (.kf)",false,()->new AlertDialog.Builder(this).setMessage("تصدير .kf غير مفعّل في هذه النسخة الأولية.").setPositiveButton("حسنًا",null).show());addButton(body,"تصدير المشروع",true,()->{resolution=res.getSelectedItem().toString();fps=Integer.parseInt(rate.getSelectedItem().toString().split(" ")[0]);new AlertDialog.Builder(this).setTitle("إعدادات التصدير محفوظة").setMessage("تم حفظ اختيار الدقة ومعدل الإطارات. يلزم تنفيذ محرك تصيير فيديو لإنتاج ملف الفيديو.").setPositiveButton("حسنًا",null).show();});addButton(body,"إلغاء",false,()->showEditor());}
  void showSettings(){page="settings";base("الإعدادات");heading("كي فلو برو");addButton(body,"حجم الواجهة",false,()->new AlertDialog.Builder(this).setItems(new String[]{"تلقائي","كبير (115%)","أكبر (130%)"},(d,w)->{}).show());heading("App");body.addView(text("SQ Motion Studio · Java prototype",13,MUTED));heading("This device");body.addView(text("Android  ·  "+android.os.Build.VERSION.RELEASE,13,MUTED));addButton(body,"العودة",true,()->showHome());}
}